head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/list_common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");
scwin.vScrenID = "ULDFIS00100_P1.gfm";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};

/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_ComList.removeAll();
    txb_TotCnt.setValue("");
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.
    if ($c.stf.getObjectValue(txb_CoSnm) == "" && $c.stf.getObjectValue(cmb_CorpRegTyp) == "" && $c.stf.getObjectValue(txb_StdIndCd) == "" && $c.stf.getObjectValue(txb_EntprGrpCd) == "") {
        alert("조회조건을 입력하세요.");
        txb_CoSnm.focus();
        return false;
    }
    return true;
};


/**
 * 기업목록 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_ComList);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.comList_p" + "&outputMessageId=FIS_COM_LIST_P" + "&param01=" + $c.stf.getObjectValue(txb_CoSnm) + "&param02=" + $c.stf.getObjectValue(cmb_CorpRegTyp) + "&param03=" + $c.stf.getObjectValue(txb_StdIndCd) + "&param04=" + $c.stf.getObjectValue(txb_EntprGrpCd);
    dts_ComList.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_ComList.Reset();
};


/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.fn_SetParam = async function(v_Currow) {
    if (v_Currow == undefined) {
        v_Currow = dts_ComList.getRowPosition();
    }
    var arrPar = new Array();
    arrPar[0] = {
        CO_SNM: dts_ComList.getCellData(v_Currow, "CO_SNM"), //기업명	
        KIS_CD: dts_ComList.getCellData(v_Currow, "KIS_CD"), //기업코드	
        IND_PTTN: dts_ComList.getCellData(v_Currow, "IND_PTTN") //업종유형
    };

	//----W-Craft WebSquare 변환 확인: fn_SetParKisCd----//
    opener.fn_SetParKisCd(arrPar);
    await $c.frame.CloseFrame();
};


/**
 * 업종검색 팝업 오픈
 */
scwin.fn_StdIndSrchOpen = async function() {
    await $c.frame.CreateDialogFrame("STD_IND_CD", "./ULDFIS00100_P2.gfm", "업종검색", 65, 90, 360 + 20, 460 + 40, "window");
};


/**
 * 업종검색 팝업으로 값을 넘김.
 */
scwin.fn_GetParStdIndCd = function(arrPar) {

};

/**
 * 업종검색 팝업에서 값을 받음.
 */
scwin.fn_SetParStdIndCd = function(arrPar) {
    txb_StdIndCd.setValue(arrPar[0].STD_IND_CD); //업종코드
    txb_StdIndNm.setValue(arrPar[0].STD_IND_NM); //업종명

};


/**
 * 기업집단검색 팝업 오픈
 */
scwin.fn_AffCoCdSrchOpen = async function() {
    await $c.frame.CreateDialogFrame("AFF_CD_CD", "./ULDFIS00100_P3.gfm", "기업집단검색", 360, 90, 226 + 20, 320 + 40, "window");
};


/**
 * 기업집단검색 팝업으로 값을 넘김.
 */
scwin.fn_GetParAffCoCd = function() {
    var arrPar = new Array();
    arrPar[0] = txb_EntprGrpNm.getValue(); // 기업집단
    return arrPar;
};


/**
 * 기업집단검색 팝업에서 값을 받음.
 */
scwin.fn_SetParAffCoCd = function(arrPar) {
    txb_EntprGrpCd.setValue(arrPar[0].ENTPR_GRP_CD); //기업집단코드
    txb_EntprGrpNm.setValue(arrPar[0].ENTPR_GRP_NM); //기업집단명

};
scwin.dts_ComList_OnLoadError = function() {
    $c.stf.alert_error(dts_ComList);
};
scwin.dts_ComList_OnLoadCompleted = function(rowcount) {
    if (dts_ComList.errorMsg) {
        alert(dts_ComList.errorMsg);
    } else {
        txb_TotCnt.setValue("총 " + rowcount + " 건");
    }
    $c.cm.CloseWin(rowcount, grd_ComList);
};
scwin.grd_ComList_OnDblClick = function(row, colid) {
    scwin.fn_SetParam(row);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top); // 패널라운드 처리


	//----W-Craft WebSquare 변환 확인: fn_GetParKisCd----//
    var arrPar = opener.fn_GetParKisCd();
    txb_CoSnm.setValue((arrPar.length > 0) ? arrPar[0] : "");
    if (txb_CoSnm.getValue() != "") {
        scwin.fn_Search();
    } else {
        txb_CoSnm.focus();
    }
};
scwin.btn_Search_onclick = function() {
    // 조회 버튼 클릭
    scwin.fn_Search();
};
scwin.img_Confirm_onclick = function() {
    // 확인버튼 클릭
    scwin.fn_SetParam();
};
scwin.img_Close_onclick = async function() {
    // 닫기 버튼 클릭
    await $c.frame.CloseFrame();
};
scwin.txb_CoSnm_onkeydown = function() {
    // 기업명 엔터
    if (event.keyCode == 13) {
        scwin.fn_Search();
    }
};
scwin.img_StdIndCd_onclick = function() {
    // 업종검색 팝업 오픈
    scwin.fn_StdIndSrchOpen();
};
scwin.img_AffCoCd_onclick = function() {
    // 기업집단검색 팝업 오픈
    scwin.fn_AffCoCdSrchOpen();
};
scwin.txb_EntprGrpNm_onkeydown = function() {
    // 기업집단검색 팝업 오픈
    if (event.keyCode == 13) {
        scwin.fn_AffCoCdSrchOpen();
    }
};
scwin.txb_EntprGrpNm_onchange = function() {
    txb_EntprGrpCd.setValue("");
};
scwin.txb_StdIndNm_onchange = function() {
    txb_StdIndCd.setValue("");
};
